package pe.edu.upeu.pago.service;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
import java.util.*;import java.math.BigDecimal;import java.time.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;
import pe.edu.upeu.pago.entity.*;import pe.edu.upeu.pago.dto.*;import pe.edu.upeu.pago.repository.*;
@ExtendWith(MockitoExtension.class) class LiquidacionServiceTest {
 @Mock LiquidacionRepository repo;@Mock LiquidacionDetalleRepository detalles;@Mock MovimientoSaldoRepository movimientos;@Mock BloqueoSaldoService bloqueo;@Mock ConstanciaLiquidacionRepository constancias;
 LiquidacionService service;Clock clock=Clock.fixed(Instant.parse("2026-10-27T15:00:00Z"),ZoneId.of("America/Lima"));
 @BeforeEach void setup(){service=new LiquidacionService(repo,detalles,movimientos,bloqueo,clock,constancias);}
 MovimientoSaldo venta(String monto){var m=new MovimientoSaldo();m.setAmbiente(AmbientePago.PRODUCCION);m.setId(1L);m.setDocenteId(7L);m.setMonto(new BigDecimal(monto));m.setConciliado(true);m.setEstado(MovimientoSaldo.EstadoMovimiento.DISPONIBLE);m.setTipo(MovimientoSaldo.TipoMovimiento.VENTA);m.setFechaCreacion(LocalDateTime.of(2026,10,1,10,0));m.setFechaDisponible(LocalDateTime.of(2026,10,8,10,0));m.setDescripcion("Venta curso");return m;}
 void generacion(List<MovimientoSaldo> libro){when(movimientos.docentesConciliados()).thenReturn(List.of(7L));when(movimientos.findByDocenteId(7L)).thenReturn(libro);when(movimientos.save(any())).thenAnswer(i->{MovimientoSaldo m=i.getArgument(0);if(m.getId()==null)m.setId(8L);return m;});when(repo.saveAndFlush(any())).thenAnswer(i->{LiquidacionDocente l=i.getArgument(0);l.setId(10L);return l;});}
 @Test void generaSoloMontoDocenteYReservaUnaVez(){generacion(List.of(venta("80.00")));var r=service.generar(LocalDate.of(2026,10,15));assertEquals(1,r.creadas());assertEquals(new BigDecimal("80.00"),r.liquidaciones().getFirst().monto());verify(bloqueo).bloquear(7L);verify(repo).saveAndFlush(any());verify(detalles).save(any());}
 @Test void periodoExistenteNoSeDuplica(){when(movimientos.docentesConciliados()).thenReturn(List.of(7L));when(repo.existsByDocenteIdAndCorteAndEstadoNot(7L,LocalDate.of(2026,10,15),LiquidacionDocente.Estado.ANULADA)).thenReturn(true);assertEquals(0,service.generar(LocalDate.of(2026,10,15)).creadas());verify(movimientos,never()).findByDocenteId(any());verify(repo,never()).saveAndFlush(any());}
 @Test void descuentaReservasYPagosAnteriores(){var previo=venta("-30.00");previo.setId(2L);previo.setEstado(MovimientoSaldo.EstadoMovimiento.PAGADO);previo.setTipo(MovimientoSaldo.TipoMovimiento.LIQUIDACION);generacion(List.of(venta("80.00"),previo));assertEquals(new BigDecimal("50.00"),service.generar(LocalDate.of(2026,10,15)).liquidaciones().getFirst().monto());}
 @Test void excluyeFondosNoConciliadosBloqueadosOFuturos(){var fin=LocalDate.of(2026,10,16).atStartOfDay();var m=venta("80.00");m.setConciliado(false);assertFalse(LiquidacionService.elegible(m,fin));m.setConciliado(true);m.setEstado(MovimientoSaldo.EstadoMovimiento.BLOQUEADO);assertFalse(LiquidacionService.elegible(m,fin));m.setEstado(MovimientoSaldo.EstadoMovimiento.DISPONIBLE);m.setFechaDisponible(fin);assertFalse(LiquidacionService.elegible(m,fin));}
 @Test void rechazaCorteAbierto(){assertThrows(IllegalArgumentException.class,()->service.generar(LocalDate.of(2026,10,31)));verifyNoInteractions(repo,movimientos,bloqueo);}
 LiquidacionDocente pendiente(){var l=new LiquidacionDocente();l.setId(10L);l.setDocenteId(7L);l.setMonto(new BigDecimal("80.00"));l.setEstado(LiquidacionDocente.Estado.PENDIENTE);l.setMovimientoId(8L);when(repo.docenteDe(10L)).thenReturn(Optional.of(7L));when(repo.bloquear(10L)).thenReturn(Optional.of(l));return l;}
 PagoLiquidacionRequest pago(String monto,boolean verificada){return new PagoLiquidacionRequest("Banco","OP-123",LocalDate.of(2026,10,27),"CCI-123","Titular de prueba",new BigDecimal(monto),verificada);}
 byte[] pdf(){return "%PDF-1.4 comprobante para pruebas".getBytes(java.nio.charset.StandardCharsets.UTF_8);}
 @Test void noMarcaPagadoSinVerificacion(){pendiente();assertThrows(IllegalArgumentException.class,()->service.pagar(10L,pago("80",false),pdf(),"application/pdf","admin"));verify(movimientos,never()).save(any());}
 @Test void noMarcaPagadoConImporteDiferente(){pendiente();assertThrows(IllegalArgumentException.class,()->service.pagar(10L,pago("79.99",true),pdf(),"application/pdf","admin"));verify(movimientos,never()).save(any());}
 @Test void noAceptaConstanciaFalsa(){pendiente();assertThrows(IllegalArgumentException.class,()->service.pagar(10L,pago("80",true),"archivo falso".getBytes(),"application/pdf","admin"));verify(movimientos,never()).save(any());}
 @Test void transferenciaDuplicadaSeRechaza(){pendiente();when(repo.existsByBancoAndFechaOperacionAndCodigoOperacionAndEstado("BANCO",LocalDate.of(2026,10,27),"OP-123",LiquidacionDocente.Estado.PAGADA)).thenReturn(true);assertThrows(IllegalArgumentException.class,()->service.pagar(10L,pago("80",true),pdf(),"application/pdf","admin"));verify(movimientos,never()).save(any());}
 @Test void pagoVerificadoSeRegistraUnaVez(){var l=pendiente();var v=venta("80.00");var reserva=venta("-80.00");reserva.setId(8L);reserva.setEstado(MovimientoSaldo.EstadoMovimiento.RESERVADO);var d=new LiquidacionDetalle();d.setMovimientoId(1L);d.setImporte(new BigDecimal("80.00"));when(detalles.findByLiquidacionIdOrderById(10L)).thenReturn(List.of(d));when(movimientos.findById(1L)).thenReturn(Optional.of(v));when(movimientos.findByDocenteId(7L)).thenReturn(List.of(v,reserva));when(movimientos.findById(8L)).thenReturn(Optional.of(reserva));assertEquals("PAGADA",service.pagar(10L,pago("80",true),pdf(),"application/pdf","admin").estado());assertEquals("PAGADA",service.pagar(10L,pago("80",true),pdf(),"application/pdf","admin").estado());verify(movimientos,times(1)).save(reserva);verify(repo,times(1)).saveAndFlush(l);assertEquals("admin",l.getVerificadoPor());assertNotNull(l.getConstanciaSha256());}
 @Test void pagoPrevioNoPuedeAnularse(){var l=pendiente();l.setEstado(LiquidacionDocente.Estado.PAGADA);assertThrows(IllegalStateException.class,()->service.anular(10L,"Motivo"));verify(movimientos,never()).save(any());}
 @Test void anulacionLiberaReserva(){var l=pendiente();var reserva=venta("-80.00");reserva.setId(8L);reserva.setEstado(MovimientoSaldo.EstadoMovimiento.RESERVADO);when(movimientos.findById(8L)).thenReturn(Optional.of(reserva));assertEquals("ANULADA",service.anular(10L,"Devolución").estado());assertEquals(MovimientoSaldo.EstadoMovimiento.REVERTIDO,reserva.getEstado());}
 @Test void informesExcluyenLiquidacionConOrigenDesconocido(){var l=new LiquidacionDocente();l.setId(10L);var d=new LiquidacionDetalle();d.setMovimientoId(1L);d.setImporte(BigDecimal.TEN);var m=venta("10");m.setAmbiente(AmbientePago.DESCONOCIDO);when(repo.findAllByOrderByIdDesc()).thenReturn(List.of(l));when(detalles.findByLiquidacionIdOrderById(10L)).thenReturn(List.of(d));when(movimientos.findById(1L)).thenReturn(Optional.of(m));assertTrue(service.listar().isEmpty());}
}
